/* eslint-disable import/no-extraneous-dependencies */
module.exports = {
  '*.js': ['eslint --fix', 'prettier --write'],
  '*.md': absolutePaths => {
    // Generated/excluded-from-markdownlint markdown: these are owned by a generator or are
    // deliberate fixtures, and re-lint with pre-existing upstream issues.
    // - packages/ui/skills/lion-ui/references/**/*.md is generated by `npm run skills:generate`
    //   (formatting owned by that script, not prettier/markdownlint).
    // - packages-node/skill-tester/mock-repo/**/*.md is a mock repository used as test input.
    const markdownlintExcludedDirs = [
      '/packages/ui/skills/lion-ui/references/',
      '/packages-node/skill-tester/mock-repo/',
    ];
    const filteredPaths = absolutePaths.filter(
      p => !markdownlintExcludedDirs.some(dir => p.includes(dir)),
    );
    if (filteredPaths.length === 0) {
      return [];
    }
    return [
      `prettier --write ${filteredPaths.join(' ')}`,
      `markdownlint --ignore '{.github/**/*.md,.changeset/*.md,**/CHANGELOG.md,packages/ui/_legacy-changelogs/*.md,packages-node/skill-tester/mock-repo/**/*.md}' ${filteredPaths.join(' ')}`,
    ];
  },
  'package-lock.json': ['node ./scripts/lock-scan.mjs'],
  '*package.json': absolutePaths => {
    const sortPackages = [];
    absolutePaths.forEach(p => {
      sortPackages.push(`node ./scripts/sort-package-json.js ${p}`);
    });
    return [...sortPackages, `node ./scripts/lint-versions.js`];
  },
};
